diff --git a/calendar/providers/caldav/modules/CalDavRequest.sys.mjs b/calendar/providers/caldav/modules/CalDavRequest.sys.mjs
index 0910bf7290c..4425d22c6c0 100644
--- a/calendar/providers/caldav/modules/CalDavRequest.sys.mjs
+++ b/calendar/providers/caldav/modules/CalDavRequest.sys.mjs
@@ -212,6 +212,11 @@ class CalDavRequestBase {

     // If any other header is used, it should be added here. We might want
     // to just copy all headers over to the new channel.
+    if (aOldChannel.URI.prePath == aNewChannel.URI.prePath) {
+      // Don't send the Authorization header to another server. Ask for
+      // authorization again.
+      copyHeader("Authorization");
+    }
     copyHeader("Depth");
     copyHeader("Originator");
     copyHeader("Recipient");
@@ -220,9 +225,7 @@ class CalDavRequestBase {
     copyHeader("Accept");

     aNewChannel.requestMethod = aOldChannel.requestMethod;
-    this.session.prepareRedirect(aOldChannel, aNewChannel).then(() => {
-      aCallback.onRedirectVerifyCallback(Cr.NS_OK);
-    });
+    aCallback.onRedirectVerifyCallback(Cr.NS_OK);
   }
 }

diff --git a/calendar/providers/caldav/modules/CalDavSession.sys.mjs b/calendar/providers/caldav/modules/CalDavSession.sys.mjs
index dab6af0e84d..e81cf749178 100644
--- a/calendar/providers/caldav/modules/CalDavSession.sys.mjs
+++ b/calendar/providers/caldav/modules/CalDavSession.sys.mjs
@@ -86,28 +86,6 @@ export class CalDavSession {
       aChannel.setRequestHeader("Authorization", `Bearer ${accessToken}`, false);
     }
   }
-
-  /**
-   * Prepare the given new channel for a redirect, e.g. copying headers.
-   *
-   * @param {nsIChannel} aOldChannel - The old channel that is being redirected
-   * @param {nsIChannel} aNewChannel - The new channel to prepare
-   * @returns {Promise} A promise resolved when the preparations are complete
-   */
-  async prepareRedirect(aOldChannel, aNewChannel) {
-    try {
-      const hdrValue = aOldChannel.getRequestHeader("Authorization");
-      if (hdrValue) {
-        aNewChannel.setRequestHeader("Authorization", hdrValue, false);
-      }
-    } catch (e) {
-      if (e.result != Cr.NS_ERROR_NOT_AVAILABLE) {
-        // The header could possibly not be available, ignore that
-        // case but throw otherwise.
-        throw e;
-      }
-    }
-  }
 }

